// src/features/academics/components/AutoAssignmentPreview.tsx
import React from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Stack,
  Chip,
  Alert,
  AlertTitle,
  CircularProgress,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  LinearProgress,
} from '@mui/material';
import {
  School as SchoolIcon,
  Person as PersonIcon,
  Assignment as AssignmentIcon,
  Warning as WarningIcon,
  Error as ErrorIcon,
  Info as InfoIcon,
  CheckCircle as CheckCircleIcon,
} from '@mui/icons-material';

import { usePreviewAssignment } from '../hooks/useHomeroom';
import type { AssignmentPreview } from '../services/homeroom';

type Props = {
  grade: string | undefined;
  teacherId: string | undefined;
  academicYearId: string | undefined;
  teacherName?: string;
};

export default function AutoAssignmentPreview({
  grade,
  teacherId,
  academicYearId,
  teacherName,
}: Props) {
  const {
    data: preview,
    isLoading,
    error,
    isFetching,
  } = usePreviewAssignment(
    grade,
    teacherId,
    { academic_year_id: academicYearId }
  );

  if (!grade || !teacherId) {
    return (
      <Alert severity="info" icon={<InfoIcon />}>
        <AlertTitle>Preview Not Available</AlertTitle>
        Please select both a teacher and grade level to see the auto-assignment preview.
      </Alert>
    );
  }

  if (isLoading) {
    return (
      <Card variant="outlined">
        <CardContent>
          <Stack direction="row" alignItems="center" spacing={2}>
            <CircularProgress size={20} />
            <Typography variant="body2">
              Loading assignment preview...
            </Typography>
          </Stack>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Alert severity="error" icon={<ErrorIcon />}>
        <AlertTitle>Preview Error</AlertTitle>
        Unable to load assignment preview. Please try again.
      </Alert>
    );
  }

  if (!preview) {
    return null;
  }

  const hasConflicts = preview.conflicts.length > 0;
  const hasErrors = preview.conflicts.some(c => c.severity === 'error');
  const hasWarnings = preview.conflicts.some(c => c.severity === 'warning');

  return (
    <Box>
      {isFetching && <LinearProgress sx={{ mb: 2 }} />}
      
      <Stack spacing={3}>
        {/* Header */}
        <Box>
          <Typography variant="h6" gutterBottom>
            Auto-Assignment Preview
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {teacherName && `${teacherName} • `}
            Grade {grade} Homeroom
          </Typography>
        </Box>

        {/* Conflicts/Warnings */}
        {hasConflicts && (
          <Alert 
            severity={hasErrors ? "error" : "warning"}
            icon={hasErrors ? <ErrorIcon /> : <WarningIcon />}
          >
            <AlertTitle>
              {hasErrors ? "Assignment Conflicts" : "Assignment Warnings"}
            </AlertTitle>
            <List dense>
              {preview.conflicts.map((conflict, index) => (
                <ListItem key={index} sx={{ py: 0.5 }}>
                  <ListItemIcon sx={{ minWidth: 36 }}>
                    {conflict.severity === 'error' ? (
                      <ErrorIcon color="error" fontSize="small" />
                    ) : (
                      <WarningIcon color="warning" fontSize="small" />
                    )}
                  </ListItemIcon>
                  <ListItemText
                    primary={conflict.message}
                    primaryTypographyProps={{ variant: 'body2' }}
                  />
                </ListItem>
              ))}
            </List>
          </Alert>
        )}

        {/* Subjects to be assigned */}
        <Card variant="outlined">
          <CardContent>
            <Stack spacing={2}>
              <Stack direction="row" alignItems="center" spacing={1}>
                <AssignmentIcon color="primary" />
                <Typography variant="subtitle1">
                  CORE Subjects to Assign
                </Typography>
              </Stack>
              
              {preview.eligible_subjects.length > 0 ? (
                <Box>
                  <Stack direction="row" spacing={1} sx={{ flexWrap: 'wrap', gap: 1 }}>
                    {preview.eligible_subjects.map((subject) => (
                      <Chip
                        key={subject.id}
                        label={subject.name}
                        size="small"
                        color={subject.is_homeroom_default ? "primary" : "default"}
                        variant={subject.is_homeroom_default ? "filled" : "outlined"}
                      />
                    ))}
                  </Stack>
                  <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                    {preview.eligible_subjects.length} subject{preview.eligible_subjects.length !== 1 ? 's' : ''} will be auto-assigned
                  </Typography>
                </Box>
              ) : (
                <Alert severity="info" sx={{ py: 1 }}>
                  No CORE subjects available for auto-assignment
                </Alert>
              )}
            </Stack>
          </CardContent>
        </Card>

        {/* Student Impact */}
        <Card variant="outlined">
          <CardContent>
            <Stack spacing={2}>
              <Stack direction="row" alignItems="center" spacing={1}>
                <PersonIcon color="primary" />
                <Typography variant="subtitle1">
                  Student Impact
                </Typography>
              </Stack>
              
              <Box>
                <Typography variant="h4" color="primary" gutterBottom>
                  {preview.estimated_students}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  estimated students will be auto-enrolled
                </Typography>
              </Box>
            </Stack>
          </CardContent>
        </Card>

        {/* Teacher Workload */}
        <Card variant="outlined">
          <CardContent>
            <Stack spacing={2}>
              <Stack direction="row" alignItems="center" spacing={1}>
                <SchoolIcon color="primary" />
                <Typography variant="subtitle1">
                  Teacher Workload Impact
                </Typography>
              </Stack>
              
              <Stack spacing={2}>
                {/* Subject Load */}
                <Box>
                  <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
                    <Typography variant="body2">Subject Assignments</Typography>
                    <Typography variant="body2" color="text.secondary">
                      {preview.teacher_workload_impact.current_subjects} → {preview.teacher_workload_impact.total_subjects}
                    </Typography>
                  </Stack>
                  <Stack direction="row" spacing={1} alignItems="center">
                    <Chip 
                      label={`${preview.teacher_workload_impact.current_subjects} current`}
                      size="small"
                      variant="outlined"
                    />
                    <Typography variant="body2">+</Typography>
                    <Chip 
                      label={`${preview.teacher_workload_impact.new_subjects} new`}
                      size="small"
                      color="primary"
                    />
                  </Stack>
                </Box>

                <Divider />

                {/* Student Load */}
                <Box>
                  <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
                    <Typography variant="body2">Student Assignments</Typography>
                    <Typography variant="body2" color="text.secondary">
                      {preview.teacher_workload_impact.current_students} → {preview.teacher_workload_impact.total_estimated_students}
                    </Typography>
                  </Stack>
                  <Stack direction="row" spacing={1} alignItems="center">
                    <Chip 
                      label={`${preview.teacher_workload_impact.current_students} current`}
                      size="small"
                      variant="outlined"
                    />
                    <Typography variant="body2">+</Typography>
                    <Chip 
                      label={`${preview.teacher_workload_impact.estimated_new_students} new`}
                      size="small"
                      color="primary"
                    />
                  </Stack>
                </Box>
              </Stack>
            </Stack>
          </CardContent>
        </Card>

        {/* Success indicator */}
        {!hasErrors && preview.eligible_subjects.length > 0 && (
          <Alert severity="success" icon={<CheckCircleIcon />}>
            <AlertTitle>Ready to Create Homeroom</AlertTitle>
            This homeroom can be created successfully with the assignments shown above.
          </Alert>
        )}
      </Stack>
    </Box>
  );
}